def control(obs):
    h = obs.get('hitch_deg', 0.0)
    cam = obs.get('views', {}).get('camera', {})
    walls = cam.get('walls', [])
    left, right = [], []
    for b, d in walls:
        rel = ((b - 180.0 + 180.0) % 360.0) - 180.0
        if abs(rel) < 85 and d < 4:
            (left if rel > 0 else right).append(d)
    steer = 0.65 * h
    if left and right:
        steer += max(-5.0, min(5.0, 1.4 * (min(left) - min(right))))
    steer = max(-10.0, min(10.0, steer))
    return (steer, -0.38, -23.0)

