import math
def control(obs):
    h = float(obs.get('hitch_deg', 0.0))
    status = obs.get('status')
    rig = obs.get('rig', {})
    rear = rig.get('trailer_rear', [-6.3, 0.0])
    view = ((obs.get('views', {}) or {}).get('direct', {}) or {})
    ox, oy = view.get('origin', [0.75, 0.0])
    rails = []
    for b, d in view.get('walls', []):
        a = math.radians(b)
        x, y = ox + d*math.cos(a), oy + d*math.sin(a)
        if x < -1.5:
            rails.append((x, y))
    left = [(x,y) for x,y in rails if y > rear[1]]
