import math
def control(obs):
    h = float(obs.get('hitch_deg', 0.0))
    status = obs.get('status')
    if status in ('PINNED', 'JACKKNIFED'):
        return (0.0, 0.35, -160.0)
    # Estimate the corridor center from rail pairs well behind the trailer.
    view = (obs.get('views', {}) or {}).get('direct', {}) or {}
    ox, oy = view.get('origin', [0.75, 0.0])
    pts = []
    for b, d in view.get('walls', []):
        a = math.radians(b)
        x, y = ox + d*math.cos(a), oy + d*math.sin(a)
        if x < -8.0:
            pts.append((x, y))
    # Use points at similar longitudinal distance, taking the widest pair.
    steer = max(-6.0, min(6.0, 1.2*h))
    if len(pts) >= 2:
        xref = min(x for x, y in pts)
        near = [(x, y) for x, y in pts if abs(x-xref) < 3.0]
        if len(near) >= 2:
            ys = [y for x, y in near]
            center = (min(ys) + max(ys)) * 0.5
            steer += max(-3.0, min(3.0, -0.35*center))
    steer = max(-8.0, min(8.0, steer))
    return (steer, -0.08, -160.0)

