import math
def control(obs):
    h = float(obs.get('hitch_deg', 0.0))
    steer = 1.15*h
    views = obs.get('views', {})
    v = views.get('direct') or views.get('periphery')
    if v:
        origin = v.get('origin', [0.0, 0.0])
        sides = [[], []]
        for b, d in v.get('walls', []):
            a = math.radians(b)
            x = origin[0] + d*math.cos(a)
            y = origin[1] + d*math.sin(a)
            if x < -0.25 and abs(y) < 5:
                sides[0 if y > 0 else 1].append((x,y))
        if sides[0] and sides[1]:
            def near(points):
                return sum(y for x,y in sorted(points, key=lambda p: abs(p[0]+1.6))[:4]) / min(4,len(points))
            center = (near(sides[0]) + near(sides[1])) * 0.5
            steer -= 7.0*center
    steer = max(-30.0, min(30.0, steer))
    return (steer, -0.55, -170.0)

